DISCORD_EPOCH_MS = 1420070400000
WORKER_BITS, PROC_BITS, SEQ_BITS = 5, 5, 12
MAX_SEQ = (1 << SEQ_BITS) - 1  # 4095

class SnowflakeGenerator:
    def __init__(self, worker_id: int, process_id: int):
        assert 0 <= worker_id < 32 and 0 <= process_id < 32
        self.worker_id = worker_id
        self.process_id = process_id
        self.last_ms = -1
        self.seq = 0

    def _now_ms(self) -> int:
        import time
        return int(time.time() * 1000)

    def _wait_next_ms(self, last_ms: int) -> int:
        now = self._now_ms()
        while now <= last_ms:
            now = self._now_ms()
        return now

    def next_id(self) -> int:
        now = self._now_ms()
        if now < self.last_ms:
            # Clock went backwards: refuse rather than risk duplicate.
            # Caller retries; monitor this branch as critical.
            raise ClockRegressionError(self.last_ms - now)
        if now == self.last_ms:
            self.seq = (self.seq + 1) & MAX_SEQ
            if self.seq == 0:
                # Exhausted 4096 IDs in this ms: stall, don't wrap.
                now = self._wait_next_ms(self.last_ms)
        else:
            self.seq = 0
        self.last_ms = now
        ts = now - DISCORD_EPOCH_MS
        return (ts << 22) | (self.worker_id << 17) | (self.process_id << 12) | self.seq

    @staticmethod
    def decode(snowflake: int) -> dict:
        ts = (snowflake >> 22) + DISCORD_EPOCH_MS
        return {
            "timestamp_ms": ts,
            "worker_id": (snowflake >> 17) & 0x1F,
            "process_id": (snowflake >> 12) & 0x1F,
            "sequence": snowflake & 0xFFF,
        }

class ClockRegressionError(Exception):
    pass
